__NUXT_JSONP__("/ar/teachers", (function(a){return {data:[{details:{slug:"ar",pageTitle:"فئات التعليم والمعلمين | Mentor Language Institute",pageDescription:a,title:"فئات التعليم والمعلمين",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"تركز الفصول الدراسية على المهارات العملية",description:[a,"وبالإضافة إلى ذلك، توفل وغيرها من دورات إعداد الامتحانات توفر استراتيجيات لحل المشاكل مع أساليبها الخاصة."]},{title:"المعلمون في المعهد",description:["يتخرج سنويا حوالي ألف ومائتين طالب من معاهد مينتور, وهذا نتيجة كفائة معلمينا و جودة تعليمنا  \u003Cbr \u002F\u003Eونحن نسعى باستمرار لتحسين مهارات المدربين من خلال الملاحظات والتقييمات وورش العمل التطوير المهني."],checklist:[{title:"متطلبات التوظيف (المرجعية لتعيين المعلمين)",lists:["خريج كلية لمدة أربع سنوات","3 سنوات من الخبرة كمعلم اللغة الإنجليزية","تدريس المؤهلات مثل تيسول","معرفة اختبارات الامتحان مثل TOEFL® \u002F GMAT®","مهارات اتصال قوية","العاطفة والالتزام للتدريس"]},{title:"طريقة الاختيار",lists:["⁻Resume والدبلوم","⁻ اختبار قواعد اللغة الإنجليزية","مقابلة","⁻Model الدرس"],note:"معدل التوظيف أقل من 20٪."}]},{title:"نظام التدريب والتقييم",description:["في معهد مالي، نتحقق من البنود الثلاثة التالية كل 12 أسبوعا للحفاظ على جودة المعلم."],listType:"decimal",lists:[" الطلاب تقييم الكتب المدرسية والمعلمين. المدربين مع معدل رضا 85٪ أو أقل يخضعون للتدريب التطوير المهني.","ملاحظات الدرس وردود الفعل المقدمة من قبل فريق أكاديمي كبير"," حلقات عمل للتدريب المهني والتدريب لتحسين التعليم"],note:"الإدارة والمدربين نسعى جاهدين لتحسين نوعية التعليم كل يوم!"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Far",extension:".json",createdAt:"2026-10-22T16:31:31.161Z",updatedAt:"2025-05-26T12:06:27.928Z"}}],fetch:{},mutations:void 0}}("في دورات اللغة الإنجليزية العامة، يكتسب الطلاب المهارات العملية باستخدام مواد العالم الحقيقي مثل المشاركات تويتر، محادثات تيد، ومقاطع الفيلم. باستخدام هذه المواد، والطلاب يكتسبون بانتظام أنماط من قواعد اللغة والكتابة والقراءة والمفردات والاستماع والتحدث.")));